    private static List<PoolMember> crewShares(Crew crew, List<CrewMember> crewMembers, Map<Long, Person> byId) {
        List<Long> ids = new ArrayList<>();
        if (byId.containsKey(crew.getLeadId())) {
            ids.add(crew.getLeadId());
